# Final evaluation of the SAM2 exemplar pipeline on GPU: counts, timings per SAM2 size, annotated outputs.
import base64, glob, io, json, os, shutil, subprocess, sys, tarfile, time
os.environ["SAM2_BUILD_CUDA"] = "0"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "ultralytics>=8.3", "albumentations>=2.0", "hydra-core", "iopath"], check=False)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-deps", "git+https://github.com/facebookresearch/sam2.git"], check=False)
W = "/kaggle/working/proj"
os.makedirs(W, exist_ok=True)
tarfile.open(fileobj=io.BytesIO(base64.b64decode("""""")), mode="r:gz").extractall(W)
data_root = os.path.dirname(os.path.dirname(glob.glob("/kaggle/input/**/data/labels.json", recursive=True)[0]))
shutil.copytree(f"{data_root}/data", f"{W}/data", dirs_exist_ok=True)
wdir = os.path.dirname(glob.glob("/kaggle/input/**/weights/item_det.pt", recursive=True)[0])
shutil.copytree(wdir, f"{W}/weights", dirs_exist_ok=True)
os.chdir(W); sys.path.insert(0, W)
import cv2, torch
from carton.pipeline import CartonVerifier
from carton.draw import annotate
labels = json.load(open("data/labels.json"))
imgs = {k: cv2.imread(f"data/raw/{k}.jpg") for k in sorted(labels)}
res = {}
for model in ["facebook/sam2.1-hiera-large", "facebook/sam2.1-hiera-base-plus", "facebook/sam2.1-hiera-small", "facebook/sam2.1-hiera-tiny", "yolo"]:
    v = CartonVerifier(device="cuda", counter="yolo" if model == "yolo" else "sam2",
                       sam_model=None if model == "yolo" else model)
    v(imgs["img_01"])
    rows = []
    for k, img in imgs.items():
        torch.cuda.synchronize(); t = time.time()
        r = v(img)
        torch.cuda.synchronize(); dt = time.time() - t
        exp = len(labels[k]["items"])
        rows.append(dict(img=k, gt=exp, count=r.count, yolo_count=r.yolo_count, review=r.review,
                         product=r.product, per_class=r.per_class, sec=round(dt, 3)))
        if model.endswith("large") or model == "yolo":
            d = f"/kaggle/working/outputs_{'sam2' if model != 'yolo' else 'yolo'}"
            os.makedirs(d, exist_ok=True)
            cv2.imwrite(f"{d}/{k}_annotated.jpg", annotate(img, r, exp))
    res[model] = rows
    print(model, "exact", sum(r["count"] == r["gt"] for r in rows), "mae",
          sum(abs(r["count"] - r["gt"]) for r in rows) / len(rows), "sec", sum(r["sec"] for r in rows) / len(rows))
    print("   ", [(r["img"][-2:], r["count"], r["gt"]) for r in rows])
    del v; torch.cuda.empty_cache()
json.dump(res, open("/kaggle/working/final_eval.json", "w"), indent=1)
print("DONE")
